#!/bin/bash
# Task 152-w10-footprint -- meshsim sim/ WORKER10 (branch sim-w10; kit: after 8194d76). TIMING TASK: keep the box quiet while it runs.
# The chip's footprint on the runner (W10; D15 as amended by D26): bench_chip on the boot, wfi and regs at one thread
# and 6 threads (9 machines a process, 3 processes): resident set after build and run, the big SRAM's 256 MB allocated
# against resident (mincore), perf's L1d and LLC load misses; the machine's caches recorded. One revision (8194d76). ~3 min.
# From an embedded kit (sim/ at each revision named above). Writes only results/152-w10-footprint/. Scratch in /tmp, removed first
# and at the end. Safe to re-run.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/152-w10-footprint; mkdir -p "$RES"; rm -f "$RES/raw.txt"
W=/tmp/w10-152-w10-footprint; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "631d41a767c59fcf596f96628cf5849d137e18dbb484efb9176affb86256ff89" ] || { echo "kit sha256 mismatch (want 631d41a767c59fcf596f96628cf5849d137e18dbb484efb9176affb86256ff89)"; exit 2; }
mkdir -p "$W/kit" && tar -xzf "$W/kit.tgz" -C "$W/kit" || exit 2
KITS="after"
FAILS=0; FAIL=0
sec() { echo; echo "==== $*  [$(date +%T)]"; }
verdict() { echo "VERDICT $1: $2"; [ "$2" = PASS ] || FAIL=1; }
START=$(date +%s)
{
sec "machine (D21)"; . "$W/kit/after/sim/tools/machine.sh" "${QUEST_P_CPUS:-}" "${QUEST_E_CPUS:-}"; machine_record "$RES/machine.txt"; uptime
echo "kit: after 8194d76"
# Shared by W10's task bodies. run TAG CPUSET cmd...: one run under taskset (and perf stat when PERF=1: cycles,
# instructions, L1d load misses, LLC load misses, summed per core type); appends "TAG <bench line> [perf: ...]" to
# $RES/raw.txt. field NAME: a key=value field of stdin's lines.
run() {
  local tag=$1 cpus=$2; shift 2
  command -v perf > /dev/null || PERF=0
  if [ "${PERF:-0}" = 1 ]; then
    taskset -c "$cpus" perf stat -x, -e cycles,instructions,L1-dcache-load-misses,LLC-load-misses -o "$W/perf.csv" -- "$@" \
      > "$W/out.txt" 2> "$W/err.txt"
  else
    taskset -c "$cpus" "$@" > "$W/out.txt" 2> "$W/err.txt"
  fi
  local rc=$?
  local line; line=$(grep -E '^(threads|chip) ' "$W/out.txt" | tail -1)
  if [ $rc -ne 0 ] || [ -z "$line" ]; then echo "RUNFAIL $tag rc=$rc: $*"; head -5 "$W/err.txt"; FAILS=$((FAILS + 1)); return 1; fi
  local pc=""
  [ "${PERF:-0}" = 1 ] && pc=" perf: $(awk -F, '$1 ~ /^[0-9]+$/ { n=split($3,a,"/"); ev=(n>1)?a[2]:a[1]; k=(a[1]=="cpu_atom")?"atom":"core";
      v[k "_" ev]+=$1 } END { for (x in v) printf "%s=%s ", x, v[x] }' "$W/perf.csv")"
  echo "$tag $line$pc" | tee -a "$RES/raw.txt"
}
field() { grep -o "$1=[^ ]*" | cut -d= -f2; }
# med TAG FIELD: the median of FIELD over raw.txt's lines starting "TAG "
med() { grep "^$1 " "$RES/raw.txt" | field "$2" | sort -g | awk '{ a[NR]=$1 } END { if (NR) print a[int((NR+1)/2)]; else print "-" }'; }
# Task body (WORKER10): the chip's footprint on the runner (D21: the machine's caches recorded by machine.sh). bench_chip
# on the boot, wfi and regs, one thread and 6 threads by tiles (9 machines a process): the process's resident set after
# build and after the run, the big SRAM's allocated against resident (mincore), and perf stat's cache misses (L1d and
# LLC load misses), against the run's cycles. 3 processes.
sec "build (clang release, D18)"
for k in $KITS; do
  ( cd "$W/kit/$k/sim" && make -j8 CC_NAME=clang MODE=release build/clang-release/bench_chip > "$RES/build-$k.log" 2>&1 ) \
    || { tail -20 "$RES/build-$k.log"; verdict "build $k" FAIL; exit 1; }
done
grep -i "cache" "$RES/machine.txt"
P1=$(take 1 "$P_ONE"); C6=$(take 6 "$PLACE")
crun() { local tag=$1 cpus=$2 k=$3; shift 3; ( cd "$W/kit/$k/sim" && run "$tag" "$cpus" ./build/clang-release/bench_chip "$@" ); }
for rep in 1 2 3; do for k in $KITS; do for p in sort wfi regs; do
  PERF=1 crun "$k one-$p" "$P1" $k --prog $p --threads 1 --cpus "$P1" --reps 9
  PERF=1 crun "$k t6-$p" "$P_CPUS" $k --prog $p --threads 6 --partition tiles --cpus "$C6" --reps 9
done; done; done
sec "summary (medians): us per cycle; RSS MB after build and run; big SRAM MB allocated, resident; L1d and LLC load misses (perf, the whole process: 10 machines built and run)"
for k in $KITS; do for p in sort wfi regs; do for t in one t6; do
  tag="$k $t-$p"
  printf "%s %-4s %-5s us=%-6s rss=%s/%s sram=%s resident=%s/%s l1d_miss=%s llc_miss=%s instr=%s\n" "$k" "$p" "$t" "$(med "$tag" us_per_cycle)" \
    "$(med "$tag" rss_mb_built)" "$(med "$tag" rss_mb_ran)" "$(med "$tag" sram_mb)" "$(med "$tag" sram_resident_mb_built)" "$(med "$tag" sram_resident_mb_ran)" \
    "$(med "$tag" core_L1-dcache-load-misses)" "$(med "$tag" core_LLC-load-misses)" "$(med "$tag" core_instructions)"
done; done; done | tee "$RES/summary.txt"
[ "$FAILS" = 0 ] && verdict "every run completed" PASS || verdict "every run completed ($FAILS failed)" FAIL
sec "done in $(($(date +%s) - START)) s"
} 2>&1 | tee "$RES/run.log"
grep '^VERDICT' "$RES/run.log" > "$RES/VERDICTS.txt"
rm -rf "$W"
grep -q ': FAIL$' "$RES/VERDICTS.txt" && exit 1
exit 0
